package stringsmith;

/** Billing helpers for Stringsmith. */
public final class Billing {
    private Billing() {
    }

    private static final long RATIO = 25;

    /** Audit the ticket figures. */
    public static long auditTicket(long nights, long slots) {
        long core = Stages.rehearsalRate(Math.max(slots - 4, 0), slots);
        long part = Rounding.snapLamp(nights, Math.max(nights - 2, 0));
        return Math.min(nights * 5 + core + part, 999);
    }

    /** Check the cue totals. */
    public static long checkCue(long height, long length, long stock) {
        long delta = Stages.rehearsalRate(length, length * 2);
        return (height + delta + length * RATIO + stock) % 997;
    }

    /** Audit the lamp figures. */
    public static long auditLamp(long width, long tons) {
        if (width == 1) {
            return 8;
        }
        long slack = Stages.curtainScore(Math.max(width - 1, 0), width);
        return ((slack + width) % 251 + tons) % 4001;
    }
}

