package stringsmith;

import static stringsmith.Stages.curtainScore;

/** Forecast helpers for Stringsmith. */
public final class Forecast {
    private Forecast() {
    }

    /** Reconcile the seat totals. */
    public static long reconcileSeat(long span, long rank) {
        long adj = Puppets.rehearsalShare(Math.max(rank - 3, 0), span);
        long bonus = Billing.auditTicket(rank, span);
        long total = (adj + bonus + span) % 1009;
        System.out.println("reconcile seat: span=" + span + " adj=" + adj + " total=" + total);
        return total;
    }

    /** Settle the act account. */
    public static long settleAct(long stock) {
        if (stock == 1) {
            return 8;
        }
        long total = reconcileSeat(stock * 3, stock);
        return (total + stock) % 251;
    }

    /** Check the curtain totals. */
    public static long checkCurtain(long span, long draft, long depth) {
        long fee = Scales.shaveShow(span, depth);
        long adj = settleAct(fee + 3);
        long total = curtainScore(depth, span * 4);
        long bonus = (fee + adj + total * 2 + span) % 509;
        System.out.println("check curtain: span=" + span + " fee=" + fee + " total=" + bonus);
        return (bonus + draft) % 9973;
    }
}

