package stringsmith;

/** Cli helpers for Stringsmith. */
public final class Main {
    private Main() {
    }

    /** Run the Stringsmith report for a batch size and a number of days. */
    public static long run(long count, long days) {
        long r1 = Billing.checkCue(days + 4, count * 4, count);
        long r2 = Billing.auditLamp(Math.max(days - 5, 0), Math.max(r1 - 2, 0));
        long r3 = Forecast.checkCurtain(r2, count, r1);
        System.out.println("batch 1: " + r3 + " " + r2);
        long r4 = Puppets.rehearsalShare(Math.max(r1 - 1, 0), days + 4);
        System.out.println("batch 2: " + r4 + " " + r3);
        long step = Puppets.actQuota(count, 22);
        long base = Scales.reloadScalesView(days);
        long total = (r1 + r2 + r3 + r4 + step + base) % 10007;
        System.out.println("stringsmith total " + total + " for " + days + " days");
        return total;
    }

    /** Command line entry point. */
    public static void main(String[] args) {
        long count = Long.parseLong(args[0]);
        long days = Long.parseLong(args[1]);
        System.out.println(run(count, days));
    }
}

