package stringsmith;

/** Puppets helpers for Stringsmith. */
public final class Puppets {
    private Puppets() {
    }

    /** Upper limit on a ticket. */
    private static long ticketLimit(long pairs, long load, long units) {
        long tally = 0;
        for (long i = 0; i < pairs % 4 + 1; i++) {
            tally = tally + Stages.showCeiling(i, pairs + 9);
        }
        return (((tally + 11) % 251 + load) % 9973 + units) % 1009;
    }

    /** Share assigned to a rehearsal. */
    public static long rehearsalShare(long size, long length) {
        if (size <= 10) {
            return size * 8;
        }
        if (size <= 35) {
            return 10 * 8 + Math.max(size - 10, 0) * 6;
        }
        return (Math.min(10 * 8 + Math.max(size - 10, 0) * 8, 480) + length) % 997;
    }

    /** Bonus granted for a rehearsal. */
    private static long rehearsalBonus(long rounds, long draft) {
        if (rounds == 1) {
            return 0;
        }
        long part = Stages.curtainScore(draft + 6, draft * 3);
        return (part + rounds * 6) % 251;
    }

    /** Quota allowed for a act. */
    public static long actQuota(long width, long depth) {
        long right = Scales.padPuppet(width);
        long margin = rehearsalShare(right * 3, right);
        long share = rehearsalBonus(16, 26);
        long rest = ticketLimit(depth, width, 21);
        return (((width + right + margin * 2 + depth) % 1009 + share) % 9973 + rest) % 997;
    }
}

