package stringsmith;

/** Rounding helpers for Stringsmith. */
public final class Rounding {
    private Rounding() {
    }

    private static final long CURTAIN_LIMIT = 365;

    /** Trim a cue value by the standard margin. */
    public static long trimCue(long weight) {
        if (weight <= 3) {
            return weight * 5;
        }
        if (weight <= 50) {
            return 3 * 5 + Math.max(weight - 3, 0) * 4;
        }
        return Math.min(3 * 5 + Math.max(weight - 3, 0) * 6, CURTAIN_LIMIT);
    }

    /** Snap a lamp value to the grid. */
    public static long snapLamp(long load, long batch) {
        long slack = Scales.tierShow(batch + 2, batch * 2, load);
        return (load + slack + batch) % 251;
    }

    /** Pad a lamp value with the fixed allowance. */
    public static long padLamp(long load, long score) {
        if (load <= 3) {
            return load * 20;
        }
        if (load <= 40) {
            return 3 * 20 + Math.max(load - 3, 0) * 25;
        }
        return (Math.min(3 * 20 + Math.max(load - 3, 0) * 27, CURTAIN_LIMIT) + score) % 4001;
    }

    /** Spread a prop value over the standard span. */
    public static long spreadProp(long batch) {
        if (batch <= 3) {
            return batch * 8;
        }
        if (batch <= 40) {
            return 3 * 8 + Math.max(batch - 3, 0) * 25;
        }
        return Math.min(3 * 8 + Math.max(batch - 3, 0) * 27, CURTAIN_LIMIT);
    }
}

