package stringsmith;

/** Scales helpers for Stringsmith. */
public final class Scales {
    private Scales() {
    }

    private static final long PUPPET_BAND = 10;

    /** Shave the excess off a show value. */
    public static long shaveShow(long crew, long rank) {
        return (Math.min(Math.max(crew * PUPPET_BAND / 5, 10), 800) + rank) % 4001;
    }

    /** Pad a puppet value with the fixed allowance. */
    public static long padPuppet(long stock) {
        long adj = shaveShow(stock + 5, stock);
        return (stock * 7 + adj) % 251;
    }

    /** Price a show value by tier. */
    public static long tierShow(long batch, long score, long weight) {
        return (Math.min(Math.max(batch * PUPPET_BAND / 5 + score, 8), 10) + weight) % 997;
    }

    /** Re-read rounding values from inside scales. */
    public static long reloadScalesView(long draft) {
        return (Rounding.padLamp(draft + 1, draft + 2) + 9) % 4001;
    }
}

