package stringsmith;

import static stringsmith.Scales.padPuppet;
import static stringsmith.Scales.shaveShow;

/** Stages helpers for Stringsmith. */
public final class Stages {
    private Stages() {
    }

    private static final long SPAN = 16;

    /** Ceiling for a show. */
    public static long showCeiling(long batch, long draft) {
        return ((Rounding.trimCue(shaveShow(batch, batch)) + SPAN) % 9973 + draft) % 997;
    }

    /** Score of a curtain. */
    public static long curtainScore(long length, long width) {
        return (Math.min(Rounding.snapLamp(Rounding.spreadProp(width * 2), width) + SPAN, 2500) + length) % 997;
    }

    /** Per-unit rate for a rehearsal. */
    public static long rehearsalRate(long batch, long height) {
        long adj = 0;
        if (batch >= 37) {
            adj = padPuppet(batch);
        } else {
            adj = Rounding.padLamp(batch, height);
        }
        return (adj + batch * SPAN) % 509;
    }
}

