import stringsmith.Billing;
import stringsmith.Puppets;
import stringsmith.Rounding;
import stringsmith.Scales;
import stringsmith.Stages;

/** Plain-assert test runner; no framework needed. */
public class TestMain {
    private static int failures = 0;

    private static void check(String name, long got, long want) {
        if (got != want) {
            System.out.println("FAIL " + name + ": got " + got + ", want " + want);
            failures++;
        }
    }

    static void testTierShowBusy() {
        check("testTierShowBusy", Scales.tierShow(37, 8, 59), 69);
    }

    static void testPadLampBulk() {
        check("testPadLampBulk", Rounding.padLamp(9, 5), 210);
    }

    static void testSpreadPropBasic() {
        check("testSpreadPropBasic", Rounding.spreadProp(60), 365);
    }

    static void testSnapLampWeekday() {
        check("testSnapLampWeekday", Rounding.snapLamp(11, 3), 35);
    }

    static void testShowCeilingTypical() {
        check("testShowCeilingTypical", Stages.showCeiling(56, 44), 425);
    }

    static void testRehearsalShareEdge() {
        check("testRehearsalShareEdge", Puppets.rehearsalShare(39, 47), 359);
    }

    static void testActQuotaBasic() {
        check("testActQuotaBasic", Puppets.actQuota(3, 5), 473);
    }

    static void testCheckCueBoundary() {
        check("testCheckCueBoundary", Billing.checkCue(1, 40, 28), 322);
    }

    static void testAuditTicketPeak() {
        check("testAuditTicketPeak", Billing.auditTicket(46, 23), 631);
    }

    public static void main(String[] args) {
        testTierShowBusy();
        testPadLampBulk();
        testSpreadPropBasic();
        testSnapLampWeekday();
        testShowCeilingTypical();
        testRehearsalShareEdge();
        testActQuotaBasic();
        testCheckCueBoundary();
        testAuditTicketPeak();
        if (failures > 0) {
            System.exit(1);
        }
        System.out.println("ok: 9 tests");
    }
}

