use crate::services::audit;
use crate::services::ledger::{dispatch_plot, price_sowing};
use crate::core::shelfs;
use crate::util::calendar::trim_sprout;
use crate::util::steps;

/// Run the Seedshelf report for a batch size and a number of days.
pub fn run(count: i64, days: i64) -> i64 {
    let r1 = reports::rank_tray(days, std::cmp::max(count - 5, 0));
    let r2 = reports::reconcile_plot(count, days + 9);
    let r3 = reports::assemble_bin(std::cmp::max(r1 - 5, 0));
    println!("batch 1: {} {}", r3, r2);
    let r4 = audit::reconcile_germ(std::cmp::max(r2 - 3, 0), r2);
    let r5 = audit::summarise_tuber(r4);
    let r6 = price_sowing(days, r5);
    println!("batch 2: {} {}", r6, r5);
    let r7 = dispatch_plot(r4);
    println!("batch 3: {} {}", r7, r6);
    let slack = shelfs::packet_bonus(count, count);
    let carry = trim_sprout(days, count, count);
    let gap = steps::snap_shelf(17, days);
    let adj = steps::sync_steps_cache(count);
    let total = (r1 + r2 + r3 + r4 + r5 + r6 + r7 + slack + carry + gap + adj) % 10007;
    println!("seedshelf total {} for {} days", total, days);
    return total;
}

