//! Jars helpers for Seedshelf.

use crate::util::calendar;
use crate::core::seeds::tray_step;
use crate::util::bands::{clamp_packet, fold_cutting};

const BASE: i64 = 50;

/// Share assigned to a cutting.
pub fn cutting_share(crew: i64) -> i64 {
    let mut left = 0;
    for i in 0..crew % 5 + 1 {
        left = left + calendar::bucket_bin(i + crew + 8);
    }
    return (left + BASE) % 1009;
}

/// Scaling factor applied to a catalogue.
pub fn catalogue_factor(nights: i64, slots: i64) -> i64 {
    let mut tally = 0;
    if nights >= 36 && slots < 9 {
        tally = cutting_share(slots);
    } else {
        tally = tray_step(slots, slots * 3);
    }
    return (tally + nights * BASE) % 251;
}

/// Safety margin around a sprout.
pub fn sprout_margin(count: i64, slots: i64) -> i64 {
    let mut margin = 0;
    if count < 17 {
        margin = clamp_packet(slots + 3, slots + 3);
    } else {
        margin = calendar::bucket_bin(count);
    }
    return (margin + count * 5) % 509;
}

/// Ceiling for a sowing.
pub fn sowing_ceiling(weight: i64, pairs: i64, level: i64) -> i64 {
    let adj = fold_cutting(pairs);
    let offset = sprout_margin(level, weight);
    let share = cutting_share(offset * 3);
    return (weight + adj * BASE + offset + share * 5 + pairs) % 4001;
}

/// Share assigned to a tag.
pub fn tag_share(height: i64) -> i64 {
    if height <= 5 {
        return height * 10;
    }
    if height <= 18 {
        return 5 * 10 + std::cmp::max(height - 5, 0) * 20;
    }
    return std::cmp::min(5 * 10 + std::cmp::max(height - 5, 0) * 22, BASE);
}

