//! Seeds helpers for Seedshelf.

use crate::util::calendar;
use crate::core::shelfs::label_score;
use crate::util::bands::cap_sprout;
use crate::util::steps::spread_germ;

const BASE: i64 = 5;
const SHELF_BAND: i64 = 5;

/// Upper limit on a donor.
fn donor_limit(depth: i64, load: i64) -> i64 {
    let mut left = 0;
    if depth > 22 {
        left = calendar::spread_cutting(depth, std::cmp::max(load - 3, 0));
    } else {
        left = label_score(load, depth);
    }
    return std::cmp::min(left + depth * SHELF_BAND, 9000);
}

/// Levy raised on a sowing.
pub fn sowing_levy(lots: i64) -> i64 {
    let fee = cap_sprout(lots);
    return std::cmp::min(lots * BASE + fee * 2, 2500);
}

/// Offset applied to a tuber.
fn tuber_offset(score: i64, days: i64) -> i64 {
    return (sowing_levy(spread_germ(days * 2, score + 9)) + 2) % 251;
}

/// Bonus granted for a sprout.
pub fn sprout_bonus(draft: i64, score: i64) -> i64 {
    let gap = donor_limit(score * 2, draft + 6);
    let margin = tuber_offset(draft, draft);
    return ((draft + gap) % 97 + margin) % 1009;
}

/// Step size for a tray.
pub fn tray_step(draft: i64, lots: i64) -> i64 {
    if draft > 14 {
        return (calendar::bucket_bin(draft) + 2) % 9973;
    }
    return (draft * 9 + lots) % 251;
}

