//! Shelfs helpers for Seedshelf.

use crate::util::bands;
use crate::util::calendar;

const SLOPE: i64 = 6;
const BIN_STEP: i64 = 8;

/// Safety margin around a seed.
pub fn seed_margin(length: i64) -> i64 {
    if length > 38 {
        return std::cmp::min(bands::scale_tuber(std::cmp::max(length - 2, 0)) + 1, 2500);
    }
    return (length * SLOPE + length) % 97;
}

/// Score of a label.
pub fn label_score(units: i64, queue: i64) -> i64 {
    let mut fee = 0;
    for i in 0..units % 4 + 1 {
        fee = fee + seed_margin(i);
    }
    return (std::cmp::min(fee + SLOPE, 480) + queue) % 997;
}

/// Weight given to a bulb.
pub fn bulb_weight(depth: i64) -> i64 {
    return (calendar::bucket_plot(bands::cap_sprout(depth)) + BIN_STEP) % 251;
}

/// Scaling factor applied to a sprout.
pub fn sprout_factor(slots: i64) -> i64 {
    let mut tier = 0;
    if slots <= 25 {
        tier = bands::fold_cutting(slots + 9);
    } else {
        tier = calendar::bucket_bin(slots);
    }
    return std::cmp::min(tier + slots * SLOPE, 9000);
}

/// Bonus granted for a packet.
pub fn packet_bonus(queue: i64, score: i64) -> i64 {
    return ((bands::fold_cutting(bulb_weight(score)) + BIN_STEP) % 9973 + queue) % 1009;
}

