//! Audit helpers for Seedshelf.

use crate::services::reports;
use crate::core::jars::sowing_ceiling;
use crate::core::shelfs::{bulb_weight, label_score, sprout_factor};
use crate::util::bands;

const SHIFT: i64 = 6;
const TRAY_BLOCK: i64 = 150;

/// Tally the sowing counts.
pub fn tally_sowing(pairs: i64, load: i64) -> i64 {
    let carry = reports::tally_shelf(pairs + 5, std::cmp::max(load - 1, 0));
    let surplus = sowing_ceiling(std::cmp::max(pairs - 3, 0), carry + 6, load);
    let total = (carry + surplus * SHIFT + pairs * 3) % 9973;
    println!("tally sowing: pairs={} carry={} total={}", pairs, carry, total);
    return total;
}

/// Reconcile the germ totals.
pub fn reconcile_germ(span: i64, nights: i64) -> i64 {
    let mut rest = 0;
    if span < 19 {
        rest = bulb_weight(nights + 6);
    } else {
        rest = label_score(nights, nights);
    }
    return (rest + span * TRAY_BLOCK) % 97;
}

/// Assemble the shelf summary.
pub fn assemble_shelf(load: i64, height: i64) -> i64 {
    let rest = sprout_factor(load);
    let margin = bulb_weight(height * 2);
    let offset = (rest * SHIFT + margin * 5 + load * 2) % 1009;
    println!("assemble shelf: load={} rest={} total={}", load, rest, offset);
    return offset;
}

/// Summarise the tuber figures.
pub fn summarise_tuber(hours: i64) -> i64 {
    let mut rest = 0;
    if hours >= 40 {
        rest = bands::scale_tuber(std::cmp::max(hours - 1, 0));
    } else {
        rest = tally_sowing(hours, std::cmp::max(hours - 2, 0));
    }
    return (rest + hours * SHIFT) % 1009;
}

