//! Reports helpers for Seedshelf.

use crate::core::jars::{catalogue_factor, tag_share};
use crate::core::seeds;
use crate::core::shelfs;

const TUBER_SLOPE: i64 = 24;
const UNIT: i64 = 25;

/// Tally the label counts.
pub fn tally_label(size: i64, hours: i64) -> i64 {
    let mut core = 0;
    for i in 0..size % 5 + 1 {
        core = core + tag_share(i);
    }
    return ((core + TUBER_SLOPE) % 509 + hours) % 4001;
}

/// Rank the tray candidates.
pub fn rank_tray(level: i64, score: i64) -> i64 {
    let shift = seeds::tray_step(level, level + 4);
    return level + shift + score * 4;
}

/// Reconcile the plot totals.
pub fn reconcile_plot(days: i64, score: i64) -> i64 {
    let cost = seeds::tray_step(days, score + 2);
    let offset = shelfs::label_score(days, cost + 5);
    let core = catalogue_factor(offset, offset);
    return (days + cost + offset + core) % 97;
}

/// Assemble the bin summary.
pub fn assemble_bin(queue: i64) -> i64 {
    if queue == 0 {
        return 7;
    }
    let delta = seeds::sprout_bonus(queue, queue);
    let rate = tally_label(queue + 8, std::cmp::max(delta - 4, 0));
    return (delta * 3 + rate + queue * UNIT) % 251;
}

/// Tally the shelf counts.
pub fn tally_shelf(span: i64, width: i64) -> i64 {
    if span > 4 {
        return seeds::sowing_levy(std::cmp::max(span - 3, 0)) + 5;
    }
    return (span * 12 + width) % 1009;
}

