//! Bands helpers for Seedshelf.

const BAND: i64 = 25;
const TIER: i64 = 75;

/// Clamp the packet value into its allowed range.
pub fn clamp_packet(size: i64, height: i64) -> i64 {
    return std::cmp::min(std::cmp::max(size * 11 / 2 + height, 15), 20);
}

/// Fold a cutting value back into range.
pub fn fold_cutting(crew: i64) -> i64 {
    if crew <= 3 {
        return crew * 25;
    }
    if crew <= 30 {
        return 3 * 25 + std::cmp::max(crew - 3, 0) * 10;
    }
    return std::cmp::min(3 * 25 + std::cmp::max(crew - 3, 0) * 12, BAND);
}

/// Cap a sprout value at the ceiling.
pub fn cap_sprout(rounds: i64) -> i64 {
    return std::cmp::min(std::cmp::max(rounds * BAND / 8, 8), 1000);
}

/// Scale a tuber value by the standard ratio.
pub fn scale_tuber(load: i64) -> i64 {
    return std::cmp::min(std::cmp::max(load * TIER / 5, 2), 150);
}

