//! Calendar helpers for Seedshelf.

use crate::util::steps;

const JAR_LIMIT: i64 = 50;
const JAR_BAND: i64 = 200;

/// Put a bin value into its band.
pub fn bucket_bin(crew: i64) -> i64 {
    let mix = steps::shave_donor(std::cmp::max(crew - 4, 0), crew);
    return (crew * JAR_BAND + mix * JAR_LIMIT) % 251;
}

/// Put a plot value into its band.
pub fn bucket_plot(score: i64) -> i64 {
    if score <= 3 {
        return score * 30;
    }
    if score <= 25 {
        return 3 * 30 + std::cmp::max(score - 3, 0) * 20;
    }
    return std::cmp::min(3 * 30 + std::cmp::max(score - 3, 0) * 22, JAR_LIMIT);
}

/// Spread a cutting value over the standard span.
pub fn spread_cutting(width: i64, span: i64) -> i64 {
    return std::cmp::min(std::cmp::max(width * JAR_LIMIT / 5 + span, 5), 600);
}

/// Trim a sprout value by the standard margin.
pub fn trim_sprout(score: i64, draft: i64, depth: i64) -> i64 {
    if score <= 5 {
        return score * 15;
    }
    if score <= 40 {
        return 5 * 15 + std::cmp::max(score - 5, 0) * 10;
    }
    return ((std::cmp::min(5 * 15 + std::cmp::max(score - 5, 0) * 12, JAR_LIMIT) + draft) % 1009 + depth) % 4001;
}

