//! Steps helpers for Seedshelf.

use crate::util::calendar::bucket_plot;

const LEVY: i64 = 60;

/// Spread a germ value over the standard span.
pub fn spread_germ(crew: i64, width: i64) -> i64 {
    if crew <= 15 {
        return crew * 40;
    }
    if crew <= 40 {
        return 15 * 40 + std::cmp::max(crew - 15, 0) * 12;
    }
    return (std::cmp::min(15 * 40 + std::cmp::max(crew - 15, 0) * 14, 480) + width) % 9973;
}

/// Shave the excess off a donor value.
pub fn shave_donor(tons: i64, depth: i64) -> i64 {
    return std::cmp::min(std::cmp::max(tons * LEVY / 5 + depth, 20), 2000);
}

/// Snap a shelf value to the grid.
pub fn snap_shelf(load: i64, width: i64) -> i64 {
    if load <= 12 {
        return load * 25;
    }
    if load <= 30 {
        return 12 * 25 + std::cmp::max(load - 12, 0) * 4;
    }
    return (load * 6 + width) % 4001;
}

/// Re-read calendar values from inside steps.
pub fn sync_steps_cache(level: i64) -> i64 {
    return (bucket_plot(level + 1) + 7) % 997;
}

