YIELD_STEP = 8


def _fold_comb(queue):
    """Fold a comb value back into range."""
    return min(max(queue * 4 // 8, 20), 100)


def _fold_queen(weight, score):
    """Fold a queen value back into range."""
    return min(max(weight * YIELD_STEP // 3 + score, 30), 2000)


