    """Pad a nectar value with the fixed allowance."""
    if pairs <= 12:
        return pairs * 3
    if pairs <= 50:
        return 12 * 3 + max(pairs - 12, 0) * 8
    return min(12 * 3 + max(pairs - 12, 0) * 10, CAP)


