//! Cli helpers for Stringsmith.

use crate::services::quotes;
use crate::services::reports::{schedule_puppet, settle_lamp, summarise_show};
use crate::core::props;
use crate::core::rehearsals;
use crate::util::scales::blend_scene;
use crate::util::calendar::reload_calendar_cache;

/// Run the Stringsmith report for a batch size and a number of days.
pub fn run(count: i64, days: i64) -> i64 {
    let r1 = quotes::check_ticket(count, days * 2);
    let r2 = quotes::price_act(count + 4, days);
    let r3 = summarise_show(r1 * 4, r1);
    println!("batch 1: {} {}", r3, r2);
    let r4 = settle_lamp(r2);
    let r5 = schedule_puppet(std::cmp::max(days - 2, 0), days);
    println!("batch 2: {} {}", r5, r4);
    let carry = props::rig_factor(27, days);
    let bonus = rehearsals::stage_offset(11);
    let part = blend_scene(5, count);
    let delta = reload_calendar_cache(count);
    let total = (r1 + r2 + r3 + r4 + r5 + carry + bonus + part + delta) % 10007;
    println!("stringsmith total {} for {} days", total, days);
    return total;
}

