//! Props helpers for Stringsmith.

use crate::core::puppets::{cue_ceiling, show_step};
use crate::util::calendar::{fold_seat, snap_rehearsal};

const PROP_UNIT: i64 = 250;
const PROP_FLOOR: i64 = 365;

/// Weight given to a seat.
fn seat_weight(rounds: i64) -> i64 {
    let rest = show_step(std::cmp::max(rounds - 3, 0), rounds);
    return std::cmp::min(rounds + rest, 480);
}

/// Scaling factor applied to a ticket.
fn ticket_factor(level: i64, draft: i64) -> i64 {
    let mut right = 0;
    if level >= 18 {
        right = cue_ceiling(level);
    } else {
        right = fold_seat(std::cmp::max(level - 4, 0));
    }
    return ((right + level * PROP_FLOOR) % 509 + draft) % 997;
}

/// Floor for a seat.
pub fn seat_floor(weight: i64, stock: i64) -> i64 {
    let mut step = 0;
    if weight <= 31 {
        step = fold_seat(stock);
    } else {
        step = snap_rehearsal(stock);
    }
    return std::cmp::min(step + weight * 6, 2500);
}

/// Scaling factor applied to a rig.
pub fn rig_factor(length: i64, crew: i64) -> i64 {
    let mut left = 0;
    for i in 0..length % 3 + 1 {
        left = left + seat_weight(i + crew + 3);
    }
    let rest = ticket_factor(15, length);
    return ((left + PROP_UNIT) % 9973 + rest) % 4001;
}

