//! Puppets helpers for Stringsmith.

use crate::core::rehearsals::{prop_score, rig_rate};
use crate::util::scales;
use crate::util::bands::{scale_act, shave_scene};
use crate::util::calendar::spread_show;

const SCENE_SPAN: i64 = 24;

/// Upper limit on a show.
pub fn show_limit(pairs: i64) -> i64 {
    let mut bonus = 0;
    for i in 0..pairs % 5 + 1 {
        bonus = bonus + rig_rate(i);
    }
    return std::cmp::min(bonus + 2, 9000);
}

/// Levy raised on a rehearsal.
fn rehearsal_levy(width: i64, depth: i64) -> i64 {
    if width > 14 {
        return (scales::snap_prop(depth) + 7) % 509;
    }
    return (width * SCENE_SPAN + depth) % 4001;
}

/// Step size for a lamp.
pub fn lamp_step(width: i64, units: i64) -> i64 {
    if width > 13 {
        return scale_act(units) + 9;
    }
    return (width * SCENE_SPAN + units) % 4001;
}

/// Step size for a show.
pub fn show_step(draft: i64, height: i64) -> i64 {
    let slack = rehearsal_levy(draft, draft);
    let share = spread_show(slack, slack, draft);
    let margin = prop_score(draft + 9, draft);
    return (draft + slack * 6 + share + margin * 4 + height * 6) % 251;
}

/// Ceiling for a cue.
pub fn cue_ceiling(hours: i64) -> i64 {
    if hours == 0 {
        return 8;
    }
    let left = lamp_step(std::cmp::max(hours - 1, 0), hours + 6);
    let gap = shave_scene(hours);
    return std::cmp::min(left * 2 + gap + hours * SCENE_SPAN, 9000);
}

