//! Rehearsals helpers for Stringsmith.

use crate::util::bands::shave_scene;
use crate::util::scales::smooth_show;
use crate::util::calendar::{fold_seat, snap_rehearsal, spread_show};

const CAP: i64 = 2;
const LEVY: i64 = 7;

/// Per-unit rate for a rig.
pub fn rig_rate(count: i64) -> i64 {
    let mut tally = 0;
    if count < 11 {
        tally = shave_scene(count);
    } else {
        tally = smooth_show(count, count + 5);
    }
    return (tally + count * LEVY) % 97;
}

/// Levy raised on a lamp.
pub fn lamp_levy(depth: i64, level: i64) -> i64 {
    if depth == 1 {
        return 7;
    }
    let shift = fold_seat(std::cmp::max(depth - 4, 0));
    let tally = snap_rehearsal(shift);
    return ((shift * 5 + tally * 4 + depth * 2) % 1009 + level) % 997;
}

/// Bonus granted for a stage.
fn stage_bonus(batch: i64, width: i64, score: i64) -> i64 {
    let mut carry = 0;
    if batch >= 7 {
        carry = smooth_show(batch, score * 3);
    } else {
        carry = lamp_levy(batch, score * 4);
    }
    return (carry + batch * CAP + width) % 4001;
}

/// Score of a prop.
pub fn prop_score(length: i64, score: i64) -> i64 {
    let mut mix = 0;
    for i in 0..length % 5 + 1 {
        mix = mix + spread_show(i, score, score);
    }
    let left = stage_bonus(4, 28, score);
    return ((mix + CAP) % 1009 + left) % 9973;
}

/// Offset applied to a stage.
pub fn stage_offset(batch: i64) -> i64 {
    if batch <= 3 {
        return batch * 4;
    }
    if batch <= 20 {
        return 3 * 4 + std::cmp::max(batch - 3, 0) * 20;
    }
    return std::cmp::min(3 * 4 + std::cmp::max(batch - 3, 0) * 22, 2500);
}

