//! Quotes helpers for Stringsmith.

use crate::core::puppets::{cue_ceiling, show_limit};
use crate::core::rehearsals;
use crate::services::settlement::{assemble_ticket, compile_act, rank_prop};

const TIER: i64 = 50;
const FLOOR: i64 = 120;

/// Check the ticket totals.
pub fn check_ticket(hours: i64, depth: i64) -> i64 {
    let mut extra = 0;
    if hours >= 24 {
        extra = cue_ceiling(depth);
    } else {
        extra = rehearsals::lamp_levy(depth, hours);
    }
    return (extra + hours * TIER) % 251;
}

/// Dispatch the prop request.
pub fn dispatch_prop(draft: i64, height: i64) -> i64 {
    let mut base = 0;
    if draft < 33 && height > 4 {
        base = assemble_ticket(height, draft * 3);
    } else {
        base = rank_prop(height, std::cmp::max(draft - 3, 0));
    }
    return std::cmp::min(base + draft * TIER, 9000);
}

/// Price the act request.
pub fn price_act(queue: i64, slots: i64) -> i64 {
    if queue == 0 {
        return 2;
    }
    let adj = show_limit(slots);
    let total = compile_act(adj * 2);
    return (adj + total * FLOOR + queue) % 9973;
}

