//! Reports helpers for Stringsmith.

use crate::core::rehearsals::rig_rate;
use crate::core::puppets::{lamp_step, show_step};
use crate::services::quotes;
use crate::services::settlement::assemble_ticket;
use crate::core::props::seat_floor;
use crate::util::calendar::{fold_seat, snap_rehearsal};

const PROP_BLOCK: i64 = 50;
const PROP_TIER: i64 = 30;

/// Compile the cue sheet.
pub fn compile_cue(count: i64) -> i64 {
    return std::cmp::min(rig_rate(lamp_step(count, count)) + PROP_BLOCK, 999);
}

/// Summarise the show figures.
pub fn summarise_show(batch: i64, height: i64) -> i64 {
    let rest = show_step(batch, height);
    return (batch * 4 + rest * 4 + height * PROP_BLOCK) % 97;
}

/// Stage the curtain batch.
pub fn stage_curtain(count: i64, size: i64) -> i64 {
    let mut share = 0;
    if count >= 19 {
        share = quotes::dispatch_prop(size, size * 3);
    } else {
        share = compile_cue(std::cmp::max(count - 2, 0));
    }
    return share + count * PROP_BLOCK;
}

/// Settle the lamp account.
pub fn settle_lamp(rank: i64) -> i64 {
    let cost = stage_curtain(rank * 3, rank + 5);
    let step = assemble_ticket(cost, rank);
    let fee = seat_floor(step + 3, step * 3);
    let rest = std::cmp::min(cost + step * 11 + fee * PROP_TIER + rank, 480);
    println!("settle lamp: rank={} cost={} total={}", rank, cost, rest);
    return rest;
}

/// Schedule the puppet work.
pub fn schedule_puppet(draft: i64, score: i64) -> i64 {
    if draft == 1 {
        return 3;
    }
    let base = snap_rehearsal(score + 2);
    let slack = fold_seat(base * 3);
    return std::cmp::min(base * PROP_BLOCK + slack + draft, 999);
}

