//! Settlement helpers for Stringsmith.

use crate::core::rehearsals::prop_score;
use crate::util::calendar;
use crate::core::props::seat_floor;
use crate::core::puppets::show_limit;

const SLOPE: i64 = 4;

/// Compile the act sheet.
pub fn compile_act(height: i64) -> i64 {
    if height == 0 {
        return 1;
    }
    let fee = prop_score(height * 2, height);
    return (fee + height) % 509;
}

/// Rank the prop candidates.
pub fn rank_prop(score: i64, load: i64) -> i64 {
    let shift = compile_act(std::cmp::max(load - 2, 0));
    let mix = calendar::fold_seat(shift);
    return std::cmp::min(score + shift + mix + load * 4, 9000);
}

/// Assemble the ticket summary.
pub fn assemble_ticket(level: i64, depth: i64) -> i64 {
    if level == 1 {
        return 6;
    }
    let core = seat_floor(level + 6, level);
    let delta = show_limit(depth);
    return (core * SLOPE + delta + level) % 509;
}

