//! Bands helpers for Stringsmith.

const FLOOR: i64 = 10;

/// Scale a act value by the standard ratio.
pub fn scale_act(crew: i64) -> i64 {
    return std::cmp::min(std::cmp::max(crew * FLOOR / 2, 5), 50);
}

/// Round a scene value to the nearest block.
fn round_scene(rank: i64, days: i64) -> i64 {
    return std::cmp::min(std::cmp::max(rank * FLOOR / 10 + days, 10), 100);
}

/// Shave the excess off a scene value.
pub fn shave_scene(lots: i64) -> i64 {
    let rate = round_scene(std::cmp::max(lots - 3, 0), lots);
    return (lots * 5 + rate * 3) % 509;
}

