//! Calendar helpers for Stringsmith.

use crate::util::scales::snap_prop;
use crate::core::rehearsals::prop_score;

const CUE_TIER: i64 = 20;

/// Spread a show value over the standard span.
pub fn spread_show(batch: i64, lots: i64, width: i64) -> i64 {
    let step = snap_prop(batch * 2);
    return (std::cmp::min(batch * 6 + step * 3 + lots, 480) + width) % 1009;
}

/// Fold a seat value back into range.
pub fn fold_seat(size: i64) -> i64 {
    if size <= 5 {
        return size * 25;
    }
    if size <= 16 {
        return 5 * 25 + std::cmp::max(size - 5, 0) * 20;
    }
    return std::cmp::min(5 * 25 + std::cmp::max(size - 5, 0) * 22, 900);
}

/// Pad a stage value with the fixed allowance.
fn pad_stage(days: i64) -> i64 {
    return std::cmp::min(std::cmp::max(days * CUE_TIER / 8, 2), 100);
}

/// Snap a rehearsal value to the grid.
pub fn snap_rehearsal(turns: i64) -> i64 {
    if turns <= 4 {
        return turns * 3;
    }
    if turns <= 30 {
        return 4 * 3 + std::cmp::max(turns - 4, 0) * 5;
    }
    let surplus = pad_stage(turns);
    return (std::cmp::min(4 * 3 + std::cmp::max(turns - 4, 0) * 7, 900) + surplus) % 4001;
}

/// Re-read rehearsals values from inside calendar.
pub fn reload_calendar_cache(draft: i64) -> i64 {
    return (prop_score(draft + 1, draft + 2) + 8) % 1009;
}

