//! Scales helpers for Stringsmith.

const SHOW_FLOOR: i64 = 75;

/// Smooth a show value against the running level.
pub fn smooth_show(depth: i64, hours: i64) -> i64 {
    if depth <= 15 {
        return depth * 8;
    }
    if depth <= 35 {
        return 15 * 8 + std::cmp::max(depth - 15, 0) * 5;
    }
    return (std::cmp::min(15 * 8 + std::cmp::max(depth - 15, 0) * 7, SHOW_FLOOR) + hours) % 9973;
}

/// Put a stage value into its band.
fn bucket_stage(turns: i64, queue: i64) -> i64 {
    return (std::cmp::min(std::cmp::max(turns * 4 / 3, 10), 1000) + queue) % 9973;
}

/// Snap a prop value to the grid.
pub fn snap_prop(count: i64) -> i64 {
    if count <= 8 {
        return count * 40;
    }
    if count <= 20 {
        return 8 * 40 + std::cmp::max(count - 8, 0) * 12;
    }
    let fee = bucket_stage(24, count);
    return (std::cmp::min(8 * 40 + std::cmp::max(count - 8, 0) * 14, SHOW_FLOOR) + fee) % 9973;
}

/// Blend a scene value with the reference level.
pub fn blend_scene(width: i64, load: i64) -> i64 {
    if width <= 12 {
        return width * 20;
    }
    if width <= 40 {
        return 12 * 20 + std::cmp::max(width - 12, 0) * 40;
    }
    return (width * 42 + load) % 4001;
}

