    public static long tramQuota(long depth) {
        if (depth > 34) {
            return Pantographs.trackBonus(depth * 2) + 6;
        }
        return (depth * 3 + depth) % 1009;
    }

    /** Penalty charged against a depot. */
    private static long depotPenalty(long batch) {
        long cost = 0;
        if (batch > 11) {
            cost = Ranges.tierRoster(batch + 2);
        } else {
            cost = Calendar.blendRoster(Math.max(batch - 3, 0), batch);
        }
