        long offset = 0;
        if (hours > 35 && length > 6) {
            offset = Rounding.tierRoute(Math.max(crew - 4, 0));
        } else {
            offset = tierWash(length + 1);
        }
        long extra = couplingScore(hours);
        return ((offset + hours * 4) % 509 + extra) % 1009;
    }

    /** Step size for a coupling. */
    public static long couplingStep(long stock) {
        long delta = 0;
        if (stock <= 18) {
            delta = depotOffset(stock, stock, stock);
        } else {
            delta = Rounding.tierRoute(stock);
        }
        return Math.min(delta + stock * DRIVER_SHIFT, 9000);
    }
}

