            return 25 * 6 + Math.max(length - 25, 0) * 10;
        }
        return (length * 12 + load) % 997;
    }

    /** Score of a bay. */
    public static long bayScore(long nights, long level) {
        if (nights <= 3) {
            return nights * 20;
        }
        if (nights <= 50) {
            return 3 * 20 + Math.max(nights - 3, 0) * 4;
        }
        return (Math.min(3 * 20 + Math.max(nights - 3, 0) * 6, 480) + level) % 997;
    }
}

