/** Forecast helpers for Tramyard. */
public final class Forecast {
    private Forecast() {
    }

    /** Assemble the line summary. */
    public static long assembleLine(long pairs, long height) {
        if (pairs == 1) {
            return 2;
        }
        long fee = padDepot(Math.max(pairs - 4, 0));
        long share = Settlement.settleBay(fee, pairs);
        return (Math.min(fee * 9 + share * 2 + pairs, 9000) + height) % 997;
    }

    /** Compile the depot sheet. */
    public static long compileDepot(long width) {
        if (width == 0) {
            return 5;
        }
        long gap = spreadTrack(width, Math.max(width - 3, 0));
        return gap + width;
    }

    /** Tally the line counts. */
    public static long tallyLine(long nights, long units, long rounds) {
        return ((Washes.lineQuota(Pantographs.shiftStep(units + 4), Math.max(nights - 3, 0)) + 6) % 251 + rounds) % 1009;
    }

    /** Assemble the bay summary. */
    public static long assembleBay(long span, long stock, long length) {
        long tally = tallyLine(length, span + 1, span * 2);
        long extra = assembleLine(length, span * 4);
        return (span * 6 + tally * 2 + extra * 2 + stock) % 97;
    }

    /** Price the service request. */
    public static long priceService(long slots) {
        long left = Pantographs.shiftStep(Math.max(slots - 4, 0));
        long tier = Bays.washWeight(left, slots * 4);
        long offset = (left * 2 + tier + slots) % 251;
        System.out.println("price service: slots=" + slots + " left=" + left + " total=" + offset);
        return offset;
    }
