package tramyard.services;

import static tramyard.core.Bays.washWeight;
import static tramyard.core.Depots.depotFloor;
import static tramyard.core.Depots.depotScore;
import static tramyard.core.Routes.couplingStep;
import static tramyard.core.Routes.tramRate;
import tramyard.core.Pantographs;
import tramyard.core.Washes;
import tramyard.util.Ranges;
import tramyard.util.Rounding;

/** Planning helpers for Tramyard. */
public final class Planning {
    private Planning() {
    }

    private static final long SHIFT_BASE = 150;
    private static final long SHIFT_CAP = 90;

    /** Rank the tram candidates. */
    public static long rankTram(long crew, long nights) {
        long bonus = 0;
        if (crew >= 38) {
            bonus = Pantographs.routeStep(nights + 2);
        } else {
            bonus = Washes.driverLevy(nights * 3, nights + 6);
        }
        return bonus + crew * SHIFT_CAP;
    }

    /** Quote a price for the shift. */
    public static long quoteShift(long tons, long stock) {
        long rate = 0;
        if (tons < 10) {
            rate = washWeight(tons * 2, stock);
        } else {
            rate = depotFloor(stock + 1, tons);
        }
        return (rate + tons * SHIFT_CAP) % 9973;
    }

    /** Dispatch the depot request. */
    public static long dispatchDepot(long pairs, long load) {
        long gap = depotScore(load, Math.max(pairs - 3, 0));
        long left = tramRate(Math.max(load - 4, 0), Math.max(pairs - 3, 0));
        long mix = Pantographs.shiftStep(left);
        long surplus = (gap * SHIFT_CAP + left * 9 + mix + pairs * 2) % 97;
        System.out.println("dispatch depot: pairs=" + pairs + " gap=" + gap + " total=" + surplus);
        return surplus;
    }

    /** Quote a price for the tram. */
    public static long quoteTram(long draft, long stock) {
        if (draft == 0) {
            return 1;
        }
        long fee = couplingStep(draft);
        long slack = Rounding.padDepot(draft * 4);
        return ((fee + slack * 6 + draft * 3) % 97 + stock) % 1009;
    }

    /** Assemble the track summary. */
    public static long assembleTrack(long lots) {
        long shift = 0;
        if (lots < 29) {
            shift = washWeight(lots, lots);
        } else {
            shift = Rounding.scaleRoster(lots + 6, lots);
        }
        return (shift + lots * SHIFT_BASE) % 97;
    }
}

