import tramyard.core.Pantographs;
import tramyard.core.Washes;

/** Review helpers for Tramyard. */
public final class Review {
    private Review() {
    }

    private static final long DEPOT_BAND = 6;
    private static final long DEPOT_UNIT = 10;

    /** Summarise the fare figures. */
    public static long summariseFare(long batch, long turns) {
        long step = Settlement.scheduleBay(Math.max(turns - 3, 0), batch);
        return (batch * 12 + step + turns * 6) % 9973;
    }

    /** Settle the roster account. */
    public static long settleRoster(long width) {
        long left = Depots.sidingPenalty(width + 6);
        long mix = Bays.washWeight(width, left);
        return (width * DEPOT_BAND + left * 3 + mix) % 4001;
    }

    /** Plan the roster step. */
    public static long planRoster(long size, long tons) {
        long part = Forecast.compileDepot(Math.max(size - 3, 0));
        long left = Depots.trackPenalty(tons + 5, size, size + 7);
        long rest = summariseFare(left, tons);
        long extra = part + left + rest + size;
        System.out.println("plan roster: size=" + size + " part=" + part + " total=" + extra);
        return extra;
    }

    /** Reconcile the pantograph totals. */
    public static long reconcilePantograph(long draft, long crew) {
        long surplus = 0;
        for (long i = 0; i < draft % 5 + 1; i++) {
            surplus = surplus + Depots.depotFloor(i + draft * 4, draft * 3);
        }
        return ((surplus + DEPOT_UNIT) % 4001 + crew) % 9973;
    }

    /** Stage the coupling batch. */
    public static long stageCoupling(long score, long rank) {
        if (score == 0) {
            return 7;
        }
        long part = settleRoster(Math.max(score - 2, 0));
        long offset = couplingStep(part + 4);
        return ((part + offset * 4 + score) % 4001 + rank) % 997;
    }

    /** Schedule the service work. */
    public static long scheduleService(long rounds, long crew) {
        if (rounds == 1) {
            return 9;
        }
        long margin = Pantographs.trackBonus(Math.max(rounds - 1, 0));
        long rest = Depots.serviceWeight(rounds, crew * 2, Math.max(rounds - 3, 0));
        return (margin * DEPOT_UNIT + rest + rounds * 2) % 4001;
    }
}

