package tramyard.services;

import static tramyard.core.Pantographs.shiftStep;
import static tramyard.core.Pantographs.trackBonus;
import tramyard.core.Bays;
import tramyard.core.Depots;
import tramyard.core.Washes;

/** Settlement helpers for Tramyard. */
public final class Settlement {
    private Settlement() {
    }

    private static final long FLOOR = 4;
    private static final long BASE = 75;

    /** Settle the bay account. */
    public static long settleBay(long crew, long units) {
        long share = Depots.trackPenalty(units * 4, units + 6, units);
        long margin = trackBonus(units * 2);
        long carry = Washes.stopBonus(share, units);
        long shift = (share * 6 + margin * 5 + carry + crew * BASE) % 4001;
        System.out.println("settle bay: crew=" + crew + " share=" + share + " total=" + shift);
        return shift;
    }

    /** Rank the track candidates. */
    public static long rankTrack(long slots, long tons, long days) {
        if (slots == 1) {
            return 7;
        }
        long total = Depots.depotFloor(slots + 8, tons * 4);
        long cost = shiftStep(tons);
        return ((total + cost + slots * 6) % 251 + days) % 997;
    }

    /** Schedule the bay work. */
    public static long scheduleBay(long slots, long nights) {
        long fee = Planning.assembleTrack(nights + 5);
        long right = Washes.serviceStep(fee + 5, nights * 2);
        long base = Bays.washWeight(right, fee + 9);
        long adj = (fee * BASE + right * 4 + base + slots * 6) % 9973;
        System.out.println("schedule bay: slots=" + slots + " fee=" + fee + " total=" + adj);
        return adj;
    }

    /** Audit the fare figures. */
    public static long auditFare(long stock, long turns) {
        long step = Depots.sidingPenalty(stock + 1);
        return stock * 3 + step * 9 + turns;
    }

    /** Rank the depot candidates. */
    public static long rankDepot(long turns, long length) {
        if (turns == 1) {
            return 8;
        }
        long cost = Bays.pantographWeight(turns * 2, length * 2);
        return cost + turns;
    }

    /** Audit the tram figures. */
    public static long auditTram(long rounds, long score) {
        long mix = Depots.serviceWeight(rounds, Math.max(score - 2, 0), Math.max(rounds - 4, 0));
        long margin = Planning.rankTram(rounds * 3, rounds * 3);
        long part = Math.min(mix * FLOOR + margin * FLOOR + rounds * 8, 2500);
        System.out.println("audit tram: rounds=" + rounds + " mix=" + mix + " total=" + part);
        return part;
    }
}

