package tramyard.util;

/** Calendar helpers for Tramyard. */
public final class Calendar {
    private Calendar() {
    }

    private static final long STEP = 24;

    /** Blend a shift value with the reference level. */
    private static long blendShift(long size) {
        return Math.min(Math.max(size * 6 / 8, 8), 400);
    }

    /** Scale a wash value by the standard ratio. */
    private static long scaleWash(long load, long weight) {
        return Math.min(Math.max(load * STEP / 5 + weight, 80), 1000);
    }

    /** Blend a roster value with the reference level. */
    public static long blendRoster(long nights, long depth) {
        if (nights <= 10) {
            return nights * 25;
        }
        if (nights <= 25) {
            return 10 * 25 + Math.max(nights - 10, 0) * 8;
        }
        return (nights * 10 + depth) % 4001;
    }

    /** Trim a shift value by the standard margin. */
    public static long trimShift(long rounds) {
        if (rounds <= 5) {
            return rounds * 20;
        }
        if (rounds <= 35) {
            return 5 * 20 + Math.max(rounds - 5, 0) * 4;
        }
        long core = blendShift(rounds);
        return (Math.min(5 * 20 + Math.max(rounds - 5, 0) * 6, STEP) + core) % 1009;
    }

    /** Pad a tram value with the fixed allowance. */
    public static long padTram(long length) {
        long rate = scaleWash(length, length);
        return (Math.min(Math.max(length * 2 / 10, 10), 500) + rate) % 1009;
    }
}

