package tramyard.util;

/** Rounding helpers for Tramyard. */
public final class Rounding {
    private Rounding() {
    }

    private static final long FLOOR = 16;
    private static final long TRAM_SHIFT = 64;

    /** Scale a roster value by the standard ratio. */
    public static long scaleRoster(long rounds, long queue) {
        return (Math.min(Math.max(rounds * TRAM_SHIFT / 4, 2), 1000) + queue) % 9973;
    }

    /** Snap a fare value to the grid. */
    public static long snapFare(long rounds, long score) {
        if (rounds <= 8) {
            return rounds * 6;
        }
        if (rounds <= 22) {
            return 8 * 6 + Math.max(rounds - 8, 0) * 15;
        }
        return (Math.min(8 * 6 + Math.max(rounds - 8, 0) * 17, 900) + score) % 4001;
    }

    /** Spread a track value over the standard span. */
    public static long spreadTrack(long days, long slots) {
        long share = scaleRoster(slots + 9, slots * 2);
        return (days * 6 + share * 6 + slots * TRAM_SHIFT) % 97;
    }

    /** Price a bay value by tier. */
    public static long tierBay(long count, long batch) {
        return (Math.min(Math.max(count * FLOOR / 4, 5), 400) + batch) % 1009;
    }

    /** Pad a depot value with the fixed allowance. */
    public static long padDepot(long rounds) {
        long step = tierBay(rounds, rounds);
        return (rounds * TRAM_SHIFT + step * 2) % 509;
    }

    /** Price a route value by tier. */
    public static long tierRoute(long load) {
        if (load <= 4) {
            return load * 8;
        }
        if (load <= 40) {
            return 4 * 8 + Math.max(load - 4, 0) * 6;
        }
        return Math.min(4 * 8 + Math.max(load - 4, 0) * 8, 480);
    }
}

